begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('48000000-0000-4000-8000-000000000001','cert-vet@example.test','{}'),('48000000-0000-4000-8000-000000000002','cert-staff@example.test','{}');
insert into public.user_roles(user_id,role) values('48000000-0000-4000-8000-000000000001','DVM'),('48000000-0000-4000-8000-000000000001','ADMIN') on conflict do nothing;
create temp table fx(k text primary key,id uuid); grant all on fx to authenticated;
create temp table requests(k text primary key,v jsonb); grant all on requests to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"48000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Certificate','Family','3035550100',null,'EMAIL','123 Test St, Boulder CO',null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Certificate dog','Dog','Mixed','2020-01-01','exact','Brown','female','neutered',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='client'),null,'Other dog','Dog','Mixed','2020-01-01','exact','Brown','female','neutered',null,null,null);
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}')$$,'42501','Verified veterinarian credentials and clinical acceptance are required','DVM role alone does not establish verified credentials');
reset role;
insert into public.certificate_issuers(user_id,full_name,license_number,license_state,license_expires_on,practice_name,practice_address,practice_phone,verified_at,verification_reference,clinical_acceptance_at,active) values('48000000-0000-4000-8000-000000000001','Dr Test','TEST-ONLY','CO',current_date+365,'Test practice','2619 Spruce Street, Boulder CO','3035550199',now(),'SYNTHETIC TEST VERIFICATION',now(),true);
set local role authenticated;
insert into fx select 'product',id from public.save_catalog_product(null,null,'Test rabies vaccine','vaccine','Test manufacturer','dose',3000,true);
select public.receive_inventory('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'TEST-LOT',current_date+365,'Clinic',10,'Synthetic test stock');
select public.create_billing_invoice('49000000-0000-4000-8000-000000000003',(select id from fx where k='client'));
insert into requests values('live',jsonb_build_object('pet_id',(select id from fx where k='pet'),'lot_id','49000000-0000-4000-8000-000000000002','invoice_id','49000000-0000-4000-8000-000000000003','quantity',1,'dose','1 mL','route','SC','site','right rear leg','veterinarian','Dr Test','veterinarian_license','TEST-ONLY','administered_at',now(),'next_due_on',current_date+365));
select public.record_patient_treatment('49000000-0000-4000-8000-000000000004',(select v from requests where k='live'));
insert into requests values('details','{"administrator":"Test technician","rabies_tag_number":"TEST-TAG","usda_duration":"1 year","vaccine_type":"Killed virus","size_description":"20–50 lb","initial_or_booster":"initial","owner_business_phone_unavailable":true,"supervision_attested":true}');

select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{}')$$,'23514','Refresh the certificate workspace to review patient due plans before signing','Older UI cannot silently sign undisplayed plan fields');
insert into requests select 'empty',public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}');
select is((select v->>'schema_version' from requests where k='empty'),'2','New general certificate uses v2');
select is((select jsonb_array_length(v->'due_plans') from requests where k='empty'),0,'No plans explicitly represented without inferred dates');
select public.save_vaccine_due_template('95000000-0000-4000-8000-000000000001',null,'synthetic-group','Reviewed group <script>',array[(select id from fx where k='product')],30,true,'INTERNAL TEMPLATE REVIEW');
select public.save_vaccine_due_template('95000000-0000-4000-8000-000000000002',null,'unreviewed-group','Awaiting review group',array[(select id from fx where k='product')],30,true,'INTERNAL TEMPLATE REVIEW');
create function pg_temp.plan(p_id uuid,p_pet uuid,p_template uuid,p_version integer,p_due date,p_status text) returns public.patient_vaccine_due_plans language sql as $$select public.save_patient_vaccine_due_plan(p_id,p_pet,p_version,p_template,1,(select id from fx where k='product'),null,'2026-01-01','INTERNAL SOURCE',30,p_due,p_status,false,'INTERNAL OVERRIDE','INTERNAL REVIEW')$$;
select pg_temp.plan('95000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),'95000000-0000-4000-8000-000000000001',null,'2026-02-01','current');
select pg_temp.plan('95000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),'95000000-0000-4000-8000-000000000002',null,'2026-02-02','proposed');
select pg_temp.plan('95000000-0000-4000-8000-000000000005',(select id from fx where k='other'),'95000000-0000-4000-8000-000000000001',null,'2026-03-01','current');
insert into requests select 'general',public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}');
select is((select jsonb_array_length(v->'due_plans') from requests where k='general'),2,'Current and proposed plans included only for this patient');
select is((select v#>>'{due_plans,0,reviewed_due_on}' from requests where k='general'),'2026-02-01','Reviewed patient override certified separately');
select is((select v#>'{due_plans,1,reviewed_due_on}' from requests where k='general'),'null'::jsonb,'Proposed plan does not certify an unreviewed due date');
select ok((select v::text not like '%INTERNAL%' from requests where k='general'),'Internal plan notes and provenance text omitted');
select is((select v#>>'{vaccinations,0,next_due_on}' from requests where k='general'),(current_date+365)::text,'Original administration due date preserved');
select is(public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'))->>'schema_version','1','Rabies format unchanged');
select ok(not (public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details')) ? 'due_plans'),'Rabies does not substitute a care plan date');
select throws_ok($$select public.issue_vaccine_certificate('95000000-0000-4000-8000-000000000006',(select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}',(select v from requests where k='empty'),'Dr Test',true)$$,'40001',null,'Newly added plans invalidate an earlier preview');
select public.issue_vaccine_certificate('95000000-0000-4000-8000-000000000006',(select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}',(select v from requests where k='general'),'Dr Test',true);
select ok((select attestation like '%patient due-plan snapshot%' from public.vaccine_certificates where id='95000000-0000-4000-8000-000000000006'),'Signature explicitly covers due plans');
select pg_temp.plan('95000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),'95000000-0000-4000-8000-000000000001',1,'2026-02-03','current');
select is((select snapshot#>>'{due_plans,0,reviewed_due_on}' from public.vaccine_certificates where id='95000000-0000-4000-8000-000000000006'),'2026-02-01','Issued copy retains its historical plan date');
select lives_ok($$select public.issue_vaccine_certificate('95000000-0000-4000-8000-000000000006',(select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}',(select v from requests where k='general'),'Dr Test',true)$$,'Lost-response retry still returns original signed copy after later plan revision');
select throws_ok($$select public.issue_vaccine_certificate(gen_random_uuid(),(select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}',(select v from requests where k='general'),'Dr Test',true)$$,'40001',null,'Stale plan cannot sign a new certificate');
select pg_temp.plan('95000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),'95000000-0000-4000-8000-000000000002',1,'2026-02-02','retired');
select is(jsonb_array_length(public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}')->'due_plans'),1,'Retired plan omitted from new previews');
select throws_ok($$select public.preview_vaccine_certificate_v1_internal((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}')$$,'42501',null,'Browser cannot bypass v2 review via old preview');
reset role;
select * from finish();rollback;
